INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5582315, 807911, 54645, '<td valign="top">Love it. Great comp and tones</td>', 'Love it. Great comp and tones', '2009-07-22 01:03:07.000000', NULL, 1),
(5582319, 808220, 54645, '<td valign="top">Nice to capture of his bird brain at work! ;) Bit of a WB issue</td>', 'Nice to capture of his bird brain at work! ;) Bit of a WB issue', '2009-07-22 01:04:32.000000', NULL, 1),
(5582321, 808054, 54645, '<td valign="top">like the humor, strong color</td>', 'like the humor, strong color', '2009-07-22 01:05:05.000000', NULL, 1),
(5582331, 808609, 54645, '<td valign="top">:) I have to admit, I really like the chaos of this image...harsh light on the sign has been well earned by McD, and we all know that Pigeons are survivors, so if they must, McD it is...</td>', ':) I have to admit, I really like the chaos of this image...harsh light on the sign has been well earned by McD, and we all know that Pigeons are survivors, so if they must, McD it is...', '2009-07-22 01:10:06.000000', NULL, 1),
(5582333, 808494, 54645, '<td valign="top">Wow.Great contrast and lines.</td>', 'Wow.Great contrast and lines.', '2009-07-22 01:10:37.000000', NULL, 1),
(5582369, 808630, 86447, '<td valign="top">I''m sorry this one will be leaving soon (because of the text added to the photo), but WELCOME to the challenges!<br/> <br/>Read the rules, and I look forward to seeing more from you in the future.  <br/>I like your pigeons shot ... I give it a six.</td>', 'I''m sorry this one will be leaving soon (because of the text added to the photo), but WELCOME to the challenges! Read the rules, and I look forward to seeing more from you in the future.  I like your pigeons shot ... I give it a six.', '2009-07-22 01:20:18.000000', NULL, 1),
(5582372, 808649, 86447, '<td valign="top">Overprocessed, or over cropped, but still a 6.</td>', 'Overprocessed, or over cropped, but still a 6.', '2009-07-22 01:21:09.000000', NULL, 1),
(5582419, 808700, 53814, '<td valign="top">beautiful, and love the title...</td>', 'beautiful, and love the title...', '2009-07-22 01:50:28.000000', NULL, 1),
(5582438, 808691, 60195, '<td valign="top">Absolutely love this.  Great comp, great processing.  8 (for now) :O)</td>', 'Absolutely love this.  Great comp, great processing.  8 (for now) :O)', '2009-07-22 02:02:13.000000', NULL, 1),
(5582497, 808419, 30982, '<td valign="top">LOL!  Fine looking specimens and what a lovely natural frame to present them!</td>', 'LOL!  Fine looking specimens and what a lovely natural frame to present them!', '2009-07-22 03:05:15.000000', NULL, 1),
(5582498, 808387, 30982, '<td valign="top">Excellent detail of a good healthy pigeon.  I like how you caught the bread mid-air.</td>', 'Excellent detail of a good healthy pigeon.  I like how you caught the bread mid-air.', '2009-07-22 03:06:04.000000', NULL, 1),
(5582499, 808620, 30982, '<td valign="top">Interesting coloration on this fellow!  Nice job catching the "look"!</td>', 'Interesting coloration on this fellow!  Nice job catching the "look"!', '2009-07-22 03:06:26.000000', NULL, 1),
(5582501, 808379, 30982, '<td valign="top">Very nice use of DOF - has a misty sea-morning kinda feel to it (though if that were the case, one might expect the pigeon cousin, the seagull) and I like that the three here are all marked similarly.</td>', 'Very nice use of DOF - has a misty sea-morning kinda feel to it (though if that were the case, one might expect the pigeon cousin, the seagull) and I like that the three here are all marked similarly.', '2009-07-22 03:07:22.000000', NULL, 1),
(5582503, 808156, 30982, '<td valign="top">Lovely set of hands!  Good job catching the pigeon taking food, and delightful bokeh to set him off.  Color is excellent and I quite like the wide-screen aspect ratio - fits this shot well!</td>', 'Lovely set of hands!  Good job catching the pigeon taking food, and delightful bokeh to set him off.  Color is excellent and I quite like the wide-screen aspect ratio - fits this shot well!', '2009-07-22 03:08:12.000000', NULL, 1),
(5582504, 807733, 30982, '<td valign="top">Sweet pigeon shot - seriously.  Nice over the wing look, excellent detail, and you got one with very good and interesting markings.  Also very good use of that unbroken expanse of brick to keep this sweet and simple.</td>', 'Sweet pigeon shot - seriously.  Nice over the wing look, excellent detail, and you got one with very good and interesting markings.  Also very good use of that unbroken expanse of brick to keep this sweet and simple.', '2009-07-22 03:08:57.000000', NULL, 1),
(5582519, 808604, 60195, '<td valign="top">Beautifully done.  Love the composition &amp; processing.  Best of show so far!</td>', 'Beautifully done.  Love the composition & processing.  Best of show so far!', '2009-07-22 03:38:49.000000', NULL, 1),
(5582528, 807911, 60195, '<td valign="top">Wonderful capture.  Love the DoF &amp; processing! Will be very surprised if this doesn''t ribbon :O) Bumping to 9 - and a fav.</td>', 'Wonderful capture.  Love the DoF & processing! Will be very surprised if this doesn''t ribbon :O) Bumping to 9 - and a fav.', '2009-07-22 03:46:49.000000', NULL, 1),
(5582531, 808378, 30982, '<td valign="top">Yep, these cousins will do - I do believe they are related, as in they are birds, they are scavengers, and most people find them annoying.  I think they''re gorgeous.  Nice presentation of them here!</td>', 'Yep, these cousins will do - I do believe they are related, as in they are birds, they are scavengers, and most people find them annoying.  I think they''re gorgeous.  Nice presentation of them here!', '2009-07-22 03:49:45.000000', NULL, 1),
(5582532, 807626, 30982, '<td valign="top">VERY cool use of pigeon bokeh!!  And nifty that you caught the eyelid half closed - nice glow!  Very cool pigeon shot indeed!</td>', 'VERY cool use of pigeon bokeh!!  And nifty that you caught the eyelid half closed - nice glow!  Very cool pigeon shot indeed!', '2009-07-22 03:50:28.000000', NULL, 1),
(5582533, 808612, 30982, '<td valign="top">He looks as though he''s on the "red carpet" at some swanky affair and has been caught by the flash of the paparazzi.</td>', 'He looks as though he''s on the "red carpet" at some swanky affair and has been caught by the flash of the paparazzi.', '2009-07-22 03:50:59.000000', NULL, 1),
(5582534, 808424, 30982, '<td valign="top">Nice variation of form, light, color in these guys, and the tilt suits this.</td>', 'Nice variation of form, light, color in these guys, and the tilt suits this.', '2009-07-22 03:51:29.000000', NULL, 1),
(5582536, 808542, 30982, '<td valign="top">Has a very sad feel to it - these pigeons are not joyful, but resigned to their tasks, their station.</td>', 'Has a very sad feel to it - these pigeons are not joyful, but resigned to their tasks, their station.', '2009-07-22 03:52:07.000000', NULL, 1),
(5582538, 808651, 30982, '<td valign="top">LOL!  Delightful!!</td>', 'LOL!  Delightful!!', '2009-07-22 03:52:20.000000', NULL, 1),
(5582539, 808587, 30982, '<td valign="top">LOL!  I do like this.  They all look just a wee bit on the cranky side, don''t they?  (Comment only.)</td>', 'LOL!  I do like this.  They all look just a wee bit on the cranky side, don''t they?  (Comment only.)', '2009-07-22 03:52:55.000000', NULL, 1),
(5582541, 808575, 30982, '<td valign="top">I love to watch them fly in formation.  Where I live, the do this - they swoop between buildings, above rooftops, around and back again.  You''ve caught that very well here.</td>', 'I love to watch them fly in formation.  Where I live, the do this - they swoop between buildings, above rooftops, around and back again.  You''ve caught that very well here.', '2009-07-22 03:53:49.000000', NULL, 1),
(5582543, 807477, 30982, '<td valign="top">Oh dear - I''d not be all that pleased if that were my bike, and I LIKE pigeons!  They look like it''s a chilly, nasty weather kinda day and they''re just hanging out waiting for someone to come feed them.  I like this.</td>', 'Oh dear - I''d not be all that pleased if that were my bike, and I LIKE pigeons!  They look like it''s a chilly, nasty weather kinda day and they''re just hanging out waiting for someone to come feed them.  I like this.', '2009-07-22 03:54:49.000000', NULL, 1),
(5582591, 808071, 99235, '<td valign="top">Love this. The originality, the colour of the sky, the clouds, the starkness - the loneliness of duty. Beautiful.</td>', 'Love this. The originality, the colour of the sky, the clouds, the starkness - the loneliness of duty. Beautiful.', '2009-07-22 04:48:08.000000', NULL, 1),
(5582593, 808440, 99235, '<td valign="top">great shot - love the foot inthe air. Stark and dramatic.</td>', 'great shot - love the foot inthe air. Stark and dramatic.', '2009-07-22 04:49:19.000000', NULL, 1),
(5582596, 808691, 72103, '<td valign="top">Love it, just came back and bumped up to 9......</td>', 'Love it, just came back and bumped up to 9......', '2009-07-22 04:50:15.000000', NULL, 1),
(5582598, 808378, 99235, '<td valign="top">Off topic</td>', 'Off topic', '2009-07-22 04:50:51.000000', NULL, 1),
(5582600, 808054, 99235, '<td valign="top">Clever,</td>', 'Clever,', '2009-07-22 04:51:42.000000', NULL, 1),
(5582606, 808054, 30982, '<td valign="top">Heh!!  It''s just the one feather - I wouldn''t worry about it.  He does look a bit perplexed.  I like the tight crop on the left and the good use of open space.</td>', 'Heh!!  It''s just the one feather - I wouldn''t worry about it.  He does look a bit perplexed.  I like the tight crop on the left and the good use of open space.', '2009-07-22 04:58:38.000000', NULL, 1),
(5582609, 807836, 30982, '<td valign="top">Good variation in your pigeons!</td>', 'Good variation in your pigeons!', '2009-07-22 04:58:52.000000', NULL, 1),
(5582611, 808610, 30982, '<td valign="top">Ah, very sweet - lovely in flight catch!  This goes a long way toward showing that these really are quite lovely birds despite their bad reputation.  Works quite well in B&amp;W.</td>', 'Ah, very sweet - lovely in flight catch!  This goes a long way toward showing that these really are quite lovely birds despite their bad reputation.  Works quite well in B&W.', '2009-07-22 04:59:25.000000', NULL, 1),
(5582613, 807911, 30982, '<td valign="top">Absolutely AWESOME depth of field used here.  I love the ground perspective - I tried to get a shot like this and failed miserably, so thank you for not only pulling it off, but pulling it off VERY well.  Excellent in B&amp;W, too.  (Now about the spelling of "what".....)</td>', 'Absolutely AWESOME depth of field used here.  I love the ground perspective - I tried to get a shot like this and failed miserably, so thank you for not only pulling it off, but pulling it off VERY well.  Excellent in B&W, too.  (Now about the spelling of "what".....)', '2009-07-22 05:00:27.000000', NULL, 1),
(5582614, 808489, 30982, '<td valign="top">Ha!!  Great catch!!</td>', 'Ha!!  Great catch!!', '2009-07-22 05:00:43.000000', NULL, 1),
(5582616, 808674, 30982, '<td valign="top">Awww - sweet close-up!  Very nice detail in the beak - and a different sort of beak than I''m used to with my street pigeons.</td>', 'Awww - sweet close-up!  Very nice detail in the beak - and a different sort of beak than I''m used to with my street pigeons.', '2009-07-22 05:02:55.000000', NULL, 1),
(5582617, 808564, 30982, '<td valign="top">Heh!  I like the eyes staring through the pigeon.  He looks a wee bit terrified (the pigeon, that is) and desperately trying to flee the scene before the staring eyes get him.</td>', 'Heh!  I like the eyes staring through the pigeon.  He looks a wee bit terrified (the pigeon, that is) and desperately trying to flee the scene before the staring eyes get him.', '2009-07-22 05:03:31.000000', NULL, 1),
(5582618, 808691, 30982, '<td valign="top">Nice processing and setting - really suits this flock of pigeons very well.</td>', 'Nice processing and setting - really suits this flock of pigeons very well.', '2009-07-22 05:03:57.000000', NULL, 1),
(5582620, 808613, 30982, '<td valign="top">Good choice of location to keep the background simple, and very good detail on the bird.  He looks to be a fairly experienced pigeon, though not overly old.</td>', 'Good choice of location to keep the background simple, and very good detail on the bird.  He looks to be a fairly experienced pigeon, though not overly old.', '2009-07-22 05:04:59.000000', NULL, 1),
(5582621, 807766, 30982, '<td valign="top">Awww - pigeon domestic disharmony?  Great color in this.  Hopefully they worked things out!</td>', 'Awww - pigeon domestic disharmony?  Great color in this.  Hopefully they worked things out!', '2009-07-22 05:05:44.000000', NULL, 1),
(5582622, 808390, 30982, '<td valign="top">I like this kind of view, because I think it''s nifty how they curl up their pink feetsies when they fly.</td>', 'I like this kind of view, because I think it''s nifty how they curl up their pink feetsies when they fly.', '2009-07-22 05:06:14.000000', NULL, 1),
(5582624, 808582, 29416, '<td valign="top">nice abstract.</td>', 'nice abstract.', '2009-07-22 05:09:00.000000', NULL, 1),
(5582626, 808699, 30982, '<td valign="top">Very nice in-flight catch - lovely sky that day, too!</td>', 'Very nice in-flight catch - lovely sky that day, too!', '2009-07-22 05:11:18.000000', NULL, 1),
(5582627, 808570, 30982, '<td valign="top">I like the vibrance of this setting, including the vibrance of the birds themselves.</td>', 'I like the vibrance of this setting, including the vibrance of the birds themselves.', '2009-07-22 05:11:52.000000', NULL, 1),
(5582628, 808220, 30982, '<td valign="top">Awww - but he posed so well for you!  Very good detail, good light, and an excellent pose from your subject!</td>', 'Awww - but he posed so well for you!  Very good detail, good light, and an excellent pose from your subject!', '2009-07-22 05:12:17.000000', NULL, 1),
(5582632, 808623, 30982, '<td valign="top">That''s the smallest beak I''ve ever seen on a pigeon!  Nifty bird, and a great picture of it.  (I''m going under the assumption this is indeed a pigeon of some kind.  My search engine at work won''t let me try to find out otherwise.)</td>', 'That''s the smallest beak I''ve ever seen on a pigeon!  Nifty bird, and a great picture of it.  (I''m going under the assumption this is indeed a pigeon of some kind.  My search engine at work won''t let me try to find out otherwise.)', '2009-07-22 05:15:18.000000', NULL, 1),
(5582634, 808667, 30982, '<td valign="top">Heh!  He looks like he''s smiling for you!</td>', 'Heh!  He looks like he''s smiling for you!', '2009-07-22 05:15:53.000000', NULL, 1),
(5582635, 807955, 30982, '<td valign="top">Nice job keeping the light on the bird, and using the shadow to set him off a bit!</td>', 'Nice job keeping the light on the bird, and using the shadow to set him off a bit!', '2009-07-22 05:16:16.000000', NULL, 1),
(5582637, 808581, 30982, '<td valign="top">I don''t think I''ve ever seen a banded pigeon before.  Would be interesting to find out why anyone would band a pigeon!  Nice in flight catch.  I think I may have preferred this one in B&amp;W (mostly because I prefer nearly everything in B&amp;W) since the pale aqua seems just a tad off against the gray of DPC.</td>', 'I don''t think I''ve ever seen a banded pigeon before.  Would be interesting to find out why anyone would band a pigeon!  Nice in flight catch.  I think I may have preferred this one in B&W (mostly because I prefer nearly everything in B&W) since the pale aqua seems just a tad off against the gray of DPC.', '2009-07-22 05:18:09.000000', NULL, 1),
(5582638, 808603, 30982, '<td valign="top">Fine portrait - well composed, great use of the green bokeh/bakground to show off this lovely specimen!</td>', 'Fine portrait - well composed, great use of the green bokeh/bakground to show off this lovely specimen!', '2009-07-22 05:18:40.000000', NULL, 1),
(5582640, 808321, 30982, '<td valign="top">Best title of the challenge so far.  :-)  Damn fine pigeon shot, too.</td>', 'Best title of the challenge so far.  :-)  Damn fine pigeon shot, too.', '2009-07-22 05:18:57.000000', NULL, 1),
(5582641, 807705, 30982, '<td valign="top">Yes - lovely.  Absolutely lovely.</td>', 'Yes - lovely.  Absolutely lovely.', '2009-07-22 05:19:45.000000', NULL, 1),
(5582642, 808700, 30982, '<td valign="top">Oh, this makes me smile.  EXCELLENT motion blur and perfect use of the black/white background - just enough detail to give it texture.  Really, really gorgeous.</td>', 'Oh, this makes me smile.  EXCELLENT motion blur and perfect use of the black/white background - just enough detail to give it texture.  Really, really gorgeous.', '2009-07-22 05:19:52.000000', NULL, 1),
(5582643, 808540, 30982, '<td valign="top">Now that''s close!  I like how it really brings out the detail in the chest feathers in particular.</td>', 'Now that''s close!  I like how it really brings out the detail in the chest feathers in particular.', '2009-07-22 05:20:55.000000', NULL, 1),
(5582645, 808071, 30982, '<td valign="top">Excellent use of minimalism and I like the muted color in this, particularly the smogish color at the bottom.  My only nit would be the oversharpened appearance of the tree branches.</td>', 'Excellent use of minimalism and I like the muted color in this, particularly the smogish color at the bottom.  My only nit would be the oversharpened appearance of the tree branches.', '2009-07-22 05:21:50.000000', NULL, 1),
(5582646, 808650, 30982, '<td valign="top">LOL!  Somebody had to do it.  Very fun perspective of, uh, the "act", and great bokeh!</td>', 'LOL!  Somebody had to do it.  Very fun perspective of, uh, the "act", and great bokeh!', '2009-07-22 05:22:16.000000', NULL, 1),
(5582647, 808444, 30982, '<td valign="top">Wonderful Monet-ish people-bokeh!  And very fun with the pigeon-eye view of the scene.</td>', 'Wonderful Monet-ish people-bokeh!  And very fun with the pigeon-eye view of the scene.', '2009-07-22 05:22:51.000000', NULL, 1),
(5582656, 807520, 30982, '<td valign="top">What a unique backdrop!  I''d not normally associate pigeons with cactus - and he''s got very interesting markings, too.</td>', 'What a unique backdrop!  I''d not normally associate pigeons with cactus - and he''s got very interesting markings, too.', '2009-07-22 05:38:01.000000', NULL, 1),
(5582657, 808604, 30982, '<td valign="top">Wonderful!  Very aptly titled.  When they all get to taking off, it does look like a somewhat chaotic symphony.  Quite pretty in B&amp;W as well.</td>', 'Wonderful!  Very aptly titled.  When they all get to taking off, it does look like a somewhat chaotic symphony.  Quite pretty in B&W as well.', '2009-07-22 05:38:33.000000', NULL, 1),
(5582658, 808494, 30982, '<td valign="top">VERY nice use of geometrics AND sneaking a bird in there!</td>', 'VERY nice use of geometrics AND sneaking a bird in there!', '2009-07-22 05:38:53.000000', NULL, 1),
(5582659, 808702, 30982, '<td valign="top">Very good setting to show them off - quite appropriate, actually, as they do tend to love large ornate buildings.  Lovely shades of gray in this.</td>', 'Very good setting to show them off - quite appropriate, actually, as they do tend to love large ornate buildings.  Lovely shades of gray in this.', '2009-07-22 05:39:31.000000', NULL, 1),
(5582660, 808440, 30982, '<td valign="top">It''s that first step that''s always the hardest...  :-)  Really like the pipes - definitely a different kind of setting!</td>', 'It''s that first step that''s always the hardest...  :-)  Really like the pipes - definitely a different kind of setting!', '2009-07-22 05:40:09.000000', NULL, 1),
(5582661, 808105, 30982, '<td valign="top">Heh!!  Definitely fun.  I like that you left that wee bit of graffiti with some color (and I normally don''t like selective desat) - works well with your gang theme here.  That, and your lead pigeons definitely has a "don''t mess with me" stance thing going on.</td>', 'Heh!!  Definitely fun.  I like that you left that wee bit of graffiti with some color (and I normally don''t like selective desat) - works well with your gang theme here.  That, and your lead pigeons definitely has a "don''t mess with me" stance thing going on.', '2009-07-22 05:41:05.000000', NULL, 1),
(5582667, 808694, 99547, '<td valign="top">Nice portrait and the shadow stripes add something interesting</td>', 'Nice portrait and the shadow stripes add something interesting', '2009-07-22 05:56:05.000000', NULL, 1),
(5582668, 808570, 99547, '<td valign="top">A weird and busy shot, full of colour.  I like it overall but the pigeon aspect is limited.</td>', 'A weird and busy shot, full of colour.  I like it overall but the pigeon aspect is limited.', '2009-07-22 05:56:45.000000', NULL, 1),
(5582669, 808105, 99547, '<td valign="top">lots of attitude, good viewpoint</td>', 'lots of attitude, good viewpoint', '2009-07-22 05:57:00.000000', NULL, 1),
(5582670, 808494, 99547, '<td valign="top">interesting geometry</td>', 'interesting geometry', '2009-07-22 05:57:18.000000', NULL, 1),
(5582671, 808610, 99547, '<td valign="top">nice use of cloud contrast</td>', 'nice use of cloud contrast', '2009-07-22 05:57:32.000000', NULL, 1),
(5582675, 808581, 99547, '<td valign="top">nice action</td>', 'nice action', '2009-07-22 06:05:55.000000', NULL, 1),
(5582676, 808691, 99547, '<td valign="top">nice artistic work</td>', 'nice artistic work', '2009-07-22 06:06:22.000000', NULL, 1),
(5582678, 808630, 46832, '<td valign="top">Ooohhh!!! Text!!  You''ll probably get DQ''ed.</td>', 'Ooohhh!!! Text!!  You''ll probably get DQ''ed.', '2009-07-22 06:06:56.000000', NULL, 1),
(5582679, 808501, 30982, '<td valign="top">Yep, he''s definitely headed your way!  Nice catch - I love how they tuck their feet up.  And I hope you escaped without getting "bombed".</td>', 'Yep, he''s definitely headed your way!  Nice catch - I love how they tuck their feet up.  And I hope you escaped without getting "bombed".', '2009-07-22 06:06:57.000000', NULL, 1),
(5582680, 808500, 30982, '<td valign="top">Does seem a bit lost in thought, doesn''t he?  Nice shot to show off the form, especially the irridescence around the neck.</td>', 'Does seem a bit lost in thought, doesn''t he?  Nice shot to show off the form, especially the irridescence around the neck.', '2009-07-22 06:07:33.000000', NULL, 1),
(5582682, 808413, 30982, '<td valign="top">Ah, lovely bird, this one.  A sleek model, with way cool neck feathers.  Very nice use of the low angle and shallow DOF.</td>', 'Ah, lovely bird, this one.  A sleek model, with way cool neck feathers.  Very nice use of the low angle and shallow DOF.', '2009-07-22 06:08:35.000000', NULL, 1),
(5582683, 808501, 674, '<td valign="top">pity there is not more detail in the feathers! nice timing though!</td>', 'pity there is not more detail in the feathers! nice timing though!', '2009-07-22 06:09:07.000000', NULL, 1),
(5582684, 808582, 674, '<td valign="top">Wow! lovely abstract! 9</td>', 'Wow! lovely abstract! 9', '2009-07-22 06:09:39.000000', NULL, 1),
(5582685, 808388, 30982, '<td valign="top">Poor guy!  I like the somewhat wild color variation you''ve got going here.  Kind of a overdose of Topaz thing which really sparks the neck feathers and creates that rich background.</td>', 'Poor guy!  I like the somewhat wild color variation you''ve got going here.  Kind of a overdose of Topaz thing which really sparks the neck feathers and creates that rich background.', '2009-07-22 06:09:57.000000', NULL, 1),
(5582686, 808649, 30982, '<td valign="top">And quite a good headshot it is!  He seems to be smiling for you as well.</td>', 'And quite a good headshot it is!  He seems to be smiling for you as well.', '2009-07-22 06:10:20.000000', NULL, 1),
(5582687, 808610, 674, '<td valign="top">might have more impact in colour!</td>', 'might have more impact in colour!', '2009-07-22 06:10:23.000000', NULL, 1),
(5582689, 808578, 30982, '<td valign="top">Lovely.  Though they may be messy birds to some, flying rats to others, I really do enjoy watching them fly - they''re quite lovely.  I love the use of the light post for reference and in this case I do like the featureless sky.</td>', 'Lovely.  Though they may be messy birds to some, flying rats to others, I really do enjoy watching them fly - they''re quite lovely.  I love the use of the light post for reference and in this case I do like the featureless sky.', '2009-07-22 06:11:02.000000', NULL, 1),
(5582690, 808414, 30982, '<td valign="top">Or a pigeon conference of sorts.  They seem to be up to something.  Planning something, yes?  I like this - nice combination of muted color, interesting shapes, and of course pigeons.</td>', 'Or a pigeon conference of sorts.  They seem to be up to something.  Planning something, yes?  I like this - nice combination of muted color, interesting shapes, and of course pigeons.', '2009-07-22 06:11:47.000000', NULL, 1),
(5582691, 807955, 674, '<td valign="top">pity the tail is cut off</td>', 'pity the tail is cut off', '2009-07-22 06:12:52.000000', NULL, 1),
