(5583002, 808667, 84363, '<td valign="top">Colors seem to be on the dull side.  Nothing really jumps out at me.</td>', 'Colors seem to be on the dull side.  Nothing really jumps out at me.', '2009-07-22 10:35:52.000000', NULL, 1),
