(5588288, 808582, 55838, '<td valign="top">My favorite of the challenge.  Lovely colors, motion &amp; blur.  Back to bump you up to 9.</td>', 'My favorite of the challenge.  Lovely colors, motion & blur.  Back to bump you up to 9.', '2009-07-27 19:57:49.000000', NULL, 1),
(5588296, 807911, 67145, '<td valign="top">absolutely fantastic image .. love the orientation &amp; the way you''ve caught one looking straight at you ... excellent focus on the birds but soft everywhere else .. brilliant in b&amp;w .. good luck .. 10..:)</td>', 'absolutely fantastic image .. love the orientation & the way you''ve caught one looking straight at you ... excellent focus on the birds but soft everywhere else .. brilliant in b&w .. good luck .. 10..:)', '2009-07-27 20:01:06.000000', NULL, 1),
