INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5588703, 808581, 108580, '<td valign="top">Great shot, and lots of patience! I hope I''m not too harsh as this photo must have been hard to take and I''m nowhere near this level yet; but it''s a pity the focus is a bit off.</td>', 'Great shot, and lots of patience! I hope I''m not too harsh as this photo must have been hard to take and I''m nowhere near this level yet; but it''s a pity the focus is a bit off.', '2009-07-28 06:23:26.000000', NULL, 1),
(5588704, 807477, 108580, '<td valign="top">The owner of that bike is not going to be happy when he gets back...<br/>The front three OOF birds detract a bit from the rest of the scene, but I''m no expert in composition yet...</td>', 'The owner of that bike is not going to be happy when he gets back...The front three OOF birds detract a bit from the rest of the scene, but I''m no expert in composition yet...', '2009-07-28 06:24:08.000000', NULL, 1),
(5588705, 808414, 108580, '<td valign="top">I like the overcast lighting and silver structures. The front brown wooden wall unfortunately detracts from this.</td>', 'I like the overcast lighting and silver structures. The front brown wooden wall unfortunately detracts from this.', '2009-07-28 06:24:30.000000', NULL, 1),
(5588707, 808321, 108580, '<td valign="top">I''d also be <strike>fat</strike> horizontally challenged if I lived above McD''s. Expect the call from a lawyer anytime soon... Maybe your pidgeon is trying to tell us something?</td>', 'I''d also be fat horizontally challenged if I lived above McD''s. Expect the call from a lawyer anytime soon... Maybe your pidgeon is trying to tell us something?', '2009-07-28 06:26:40.000000', NULL, 1),
(5588708, 807912, 108580, '<td valign="top">Stunning detail, especially the shimmering purples, blues and fiery eye.</td>', 'Stunning detail, especially the shimmering purples, blues and fiery eye.', '2009-07-28 06:27:30.000000', NULL, 1),
(5588715, 808700, 108580, '<td valign="top">Abstract! I like! But is it a pidgeon? ;)</td>', 'Abstract! I like! But is it a pidgeon? ;)', '2009-07-28 06:33:53.000000', NULL, 1),
(5588812, 808444, 108580, '<td valign="top">Incredibly difficult to get the dang things in focus when on the move... AF?<br/>Nice shot!</td>', 'Incredibly difficult to get the dang things in focus when on the move... AF?Nice shot!', '2009-07-28 09:02:35.000000', NULL, 1),
(5588828, 808700, 17153, '<td valign="top">love the texture and impresionistic feel of this photo, great colors</td>', 'love the texture and impresionistic feel of this photo, great colors', '2009-07-28 09:09:18.000000', NULL, 1),
(5588832, 807912, 17153, '<td valign="top">this one proves that pigeons CAN look good! great colors, pose, sharpness</td>', 'this one proves that pigeons CAN look good! great colors, pose, sharpness', '2009-07-28 09:09:22.000000', NULL, 1),
