(5588967, 808604, 86799, '<td valign="top">Symphony, or chaos?  HaHa.  I can hear the flapping!  Pretty cool.  Going to bump it by one.</td>', 'Symphony, or chaos?  HaHa.  I can hear the flapping!  Pretty cool.  Going to bump it by one.', '2009-07-28 11:52:42.000000', NULL, 1),
(5588968, 808105, 86799, '<td valign="top">Looks more like "Pigeon Pilates" class.  Pretty cool.</td>', 'Looks more like "Pigeon Pilates" class.  Pretty cool.', '2009-07-28 11:52:51.000000', NULL, 1),
(5588969, 807626, 86799, '<td valign="top">The eye is pretty distracting.</td>', 'The eye is pretty distracting.', '2009-07-28 11:52:59.000000', NULL, 1),
(5588971, 808674, 86799, '<td valign="top">Nice pic, very soft and gentle.  But not "Passenger Pigeon", as that species is extinct, since 1914.  eta: ...unless this one is stuffed, that is...</td>', 'Nice pic, very soft and gentle.  But not "Passenger Pigeon", as that species is extinct, since 1914.  eta: ...unless this one is stuffed, that is...', '2009-07-28 11:53:16.000000', NULL, 1),
(5588972, 808321, 86799, '<td valign="top">HaHa, love the title.  Might not be too far fetched!</td>', 'HaHa, love the title.  Might not be too far fetched!', '2009-07-28 11:53:24.000000', NULL, 1),
(5588973, 808501, 86799, '<td valign="top">Good catch.  Not sharp enough to be a "great" catch, but nice anyhow.  I like the translucence of the wings.</td>', 'Good catch.  Not sharp enough to be a "great" catch, but nice anyhow.  I like the translucence of the wings.', '2009-07-28 11:53:35.000000', NULL, 1),
