INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5589937, 808414, 61084, '<td valign="top"><b>Thanks to everyone for the helpful comments.</b> I was hoping to do better with this picture, but since it was my first entry EVER on DPC I''ll chalk it up to a learning experience. Considering the subject of the competition in addition to my first wade into the contest waters I know it could have been worse. It''s a good starting point, and look forward to entering more! :)<br/><br/><i>Message edited by author 2009-07-29 03:55:44.</i></td>', 'Thanks to everyone for the helpful comments. I was hoping to do better with this picture, but since it was my first entry EVER on DPC I''ll chalk it up to a learning experience. Considering the subject of the competition in addition to my first wade into the contest waters I know it could have been worse. It''s a good starting point, and look forward to entering more! :)', '2009-07-29 04:53:45.000000', '2009-07-29 04:55:44.000000', 0),
(5589943, 808674, 108580, '<td valign="top">Nice one Dan but yes, extinct. Despite Wikipedia (everyones bible) new evidence supports that hunting alone is not the sole cause of it''s extinction, but habitat destruction has played as large a role, as is even the case of the Dodo which dissapeared due to dogs and macaques being introduced to Mauritius by man. So all those "conservation" groups are starting to duck thier heads in their offices and mansions and SUV''s...just because they don''t "hunt" doesn''t mean they themselves aren''t also contributing to species demise, and if they own a cat...Enough of the lecture...<br/> <br/>Well done on your 12th, you got my 8.</td>', 'Nice one Dan but yes, extinct. Despite Wikipedia (everyones bible) new evidence supports that hunting alone is not the sole cause of it''s extinction, but habitat destruction has played as large a role, as is even the case of the Dodo which dissapeared due to dogs and macaques being introduced to Mauritius by man. So all those "conservation" groups are starting to duck thier heads in their offices and mansions and SUV''s...just because they don''t "hunt" doesn''t mean they themselves aren''t also contributing to species demise, and if they own a cat...Enough of the lecture... Well done on your 12th, you got my 8.', '2009-07-29 05:07:43.000000', NULL, 0),
(5589945, 808650, 108580, '<td valign="top">"In Flagranté" = "caught in the act" Hehe. Yup photography is not all about poise and grace ;P   Wd on a top 20!<br/><br/><i>Message edited by author 2009-07-29 04:13:40.</i></td>', '"In Flagranté" = "caught in the act" Hehe. Yup photography is not all about poise and grace ;P   Wd on a top 20!', '2009-07-29 05:13:18.000000', '2009-07-29 05:13:40.000000', 0),
